// expo-audio's playback notification hard-codes media3's generic "circular play" small icon.
// An app resource with the same name wins over the library's, so point it at hush's moon
// (drawable/notification_icon, generated by the expo-notifications plugin).
const { withDangerousMod } = require("expo/config-plugins");
const fs = require("fs");
const path = require("path");

module.exports = (config) =>
  withDangerousMod(config, ["android", (cfg) => {
    const dir = path.join(cfg.modRequest.platformProjectRoot, "app/src/main/res/drawable");
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(
      path.join(dir, "media3_icon_circular_play.xml"),
      `<?xml version="1.0" encoding="utf-8"?>\n<bitmap xmlns:android="http://schemas.android.com/apk/res/android" android:src="@drawable/notification_icon" />\n`,
    );
    return cfg;
  }]);
